mapper.sql:
WHERE i.status = 'PUBLIC'

    AND i.type = #{type}


    AND i.category = #{category}


    AND i.location LIKE CONCAT('%', #{location}, '%')


    AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.description LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT i.id, i.type, i.title, i.description, i.category, i.location, i.happen_time, i.color, i.status, i.publisher_id, i.created_at, i.verify_question, u.username AS publisher_name
, i.review_opinion, i.contact, i.hidden_feature, i.verify_answer
FROM item i LEFT JOIN sys_user u ON u.id = i.publisher_id WHERE i.id = #{id}

SELECT , i.review_opinion, i.contact, i.verify_question
FROM item i
WHERE i.publisher_id = #{publisherId}

    AND i.status = #{status}

ORDER BY i.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM item i
WHERE i.publisher_id = #{publisherId}

    AND i.status = #{status}

SELECT i.id, i.type, i.title, i.description, i.category, i.location, i.happen_time, i.color, i.status, i.publisher_id, i.created_at, i.review_opinion, i.contact, i.hidden_feature, i.verify_question, i.verify_answer, u.username AS publisher_name FROM item i LEFT JOIN sys_user u ON u.id = i.publisher_id
AND i.status = #{status}
AND i.type = #{type}
AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY i.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM item i


        AND i.status = #{status}


        AND i.type = #{type}


        AND (i.title LIKE CONCAT('%', #{keyword}, '%') OR i.description LIKE CONCAT('%', #{keyword}, '%'))

SELECT *
FROM item
WHERE type = #{type}
  AND status = 'PUBLIC'
ORDER BY id DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM item
WHERE status = #{status}
  AND type = #{type}
